package com.manageinvoice.invoices;
import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
import org.springframework.stereotype.Service;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper;
@Service public class DocumentInvoiceCreationService {
 private final InvoiceRepository invoices; private final ObjectMapper mapper;
 public DocumentInvoiceCreationService(InvoiceRepository invoices,ObjectMapper mapper){this.invoices=invoices;this.mapper=mapper;}
 public void createInvoice(UUID workspaceId,UUID documentId,String correctedJson){try{JsonNode data=mapper.readTree(correctedJson);if(invoices.existsByWorkspaceIdAndDocumentId(workspaceId,documentId))return;BigDecimal total=new BigDecimal(amount(data,"total"));Invoice invoice=new Invoice();invoice.setWorkspaceId(workspaceId);invoice.setDocumentId(documentId);invoice.setInvoiceNumber(text(data,"documentNumber"));invoice.setInvoiceDate(date(data,"documentDate"));invoice.setDueDate(date(data,"dueDate"));invoice.setSubtotal(new BigDecimal(amount(data,"subtotal")));invoice.setTaxAmount(new BigDecimal(amount(data,"tax")));invoice.setTotalAmount(total);invoice.setAmountPaid(BigDecimal.ZERO);invoice.setBalanceDue(total);invoice.setCurrency(text(data,"currency","USD").toUpperCase());invoice.setStatus("RECEIVED");invoices.save(invoice);}catch(Exception exception){throw new IllegalStateException("Unable to create invoice from approved document",exception);}}
 private String amount(JsonNode data,String field){String value=text(data,field,"0");return value.replaceAll("[^0-9.-]","");}
 private String text(JsonNode data,String field){return text(data,field,null);} private String text(JsonNode data,String field,String fallback){JsonNode value=data.get(field);return value==null||value.isNull()?fallback:value.asText(fallback);} private LocalDate date(JsonNode data,String field){String value=text(data,field,null);if(value==null||value.isBlank())return null;return LocalDate.parse(value);} }
